/**
 * Lossless bindings of qa/pos/freezes/employee-policy-authoring-v2/fixtures.json.
 * Its semantic values, rather than production-derived expected data, are the oracle.
 * This helper creates DATA only. It creates no native action, approval or authority.
 */
internal object EmployeePolicyAuthoringFixtures {
    const val frozenSpecificationVersion = 2
    const val frozenSpecificationSource = "qa/pos/freezes/employee-policy-authoring-v2/FREEZE.json"
    private val root = Json.parseToJsonElement(FROZEN_FIXTURES_JSON).jsonObject
    val scope: BranchScope get() = branch(root.getValue("scope").jsonObject)
    val employee: DomainId get() = id("employee_a")
    val originalRequest: DomainId get() = journeyId("controlled_original_request")
    val originalAction: DomainId get() = journeyId("controlled_action")
    val alternativeRequest: DomainId get() = journeyId("alternate_original_request")
    val secret: String get() = root.getValue("secret_fixture").jsonObject.getValue("controlled_ascii").jsonPrimitive.content
    val secretWithTail: CharArray get() = (secret.toList() +
        root.getValue("secret_fixture").jsonObject.getValue("tail_variant").jsonObject.getValue("tail_bytes")
            .jsonArray.map { it.jsonPrimitive.int.toChar() }).toCharArray()

    fun id(name: String): DomainId = DomainId(root.getValue("ids").jsonObject.getValue(name).jsonPrimitive.content)
    fun journeyId(name: String): DomainId = DomainId(root.getValue("journey").jsonObject.getValue(name).jsonPrimitive.content)
    fun input(name: String = "replacement_policy"): JsonObject =
        (root[name] ?: root.getValue("profiles").jsonObject.getValue(name)).jsonObject
    fun invalidNumeric(name: String): JsonObject = root.getValue("numeric_invalid").jsonObject.getValue(name).jsonObject
    fun invalidGrant(name: String): JsonElement = root.getValue("grant_invalid").jsonObject.getValue(name)
    fun policy(name: String = "replacement_policy"): ActivatedLocalPolicy = bindPolicy(input(name))

    fun patchedNumeric(name: String): ActivatedLocalPolicy {
        val patch = invalidNumeric(name)
        val path = patch.getValue("path").jsonPrimitive.content.split('.')
        val original = input()
        val parent = original.getValue(path[0]).jsonObject
        return bindPolicy(JsonObject(original + (path[0] to JsonObject(parent + (path[1] to patch.getValue("value"))))))
    }

    fun bindPolicy(value: JsonObject): ActivatedLocalPolicy = ActivatedLocalPolicy(
        branch(value.getValue("scope").jsonObject), DomainId(value.getValue("actorId").jsonPrimitive.content),
        Revision(value.getValue("revision").jsonPrimitive.long),
        value.getValue("grants").jsonArray.map { bindGrant(it.jsonObject) },
        LocalSessionPolicy(value.getValue("sessionPolicy").jsonObject.getValue("maximumConcurrentSessions").jsonPrimitive.int),
        value.getValue("throttlePolicy").jsonObject.let {
            ThrottlePolicy(it.getValue("freeFailures").jsonPrimitive.int, it.getValue("initialDelayMillis").jsonPrimitive.long,
                it.getValue("maximumDelayMillis").jsonPrimitive.long, it.getValue("attemptTimeoutMillis").jsonPrimitive.long)
        },
        value.getValue("approvalPolicy").present()?.jsonObject?.let {
            LocalApprovalPolicy(it.getValue("validForMillis").jsonPrimitive.long,
                it.getValue("namedSelfApprovalActions").jsonArray.map { action -> SecurityAction.valueOf(action.jsonPrimitive.content) }.toSet())
        },
    )

    fun bindGrant(value: JsonObject): PermissionGrant = PermissionGrant(
        value.getValue("permission").jsonObject.let {
            Permission(SecurityAction.valueOf(it.getValue("action").jsonPrimitive.content),
                PermissionVerb.valueOf(it.getValue("verb").jsonPrimitive.content))
        },
        branch(value.getValue("scope").jsonObject), GrantEffect.valueOf(value.getValue("effect").jsonPrimitive.content),
        bindLimits(value.getValue("limits").jsonObject), OwnerAccess.valueOf(value.getValue("ownerAccess").jsonPrimitive.content),
        value.getValue("namedSubjectId").present()?.jsonPrimitive?.content?.let(::DomainId),
        value.getValue("targetIds").present()?.jsonArray?.map { DomainId(it.jsonPrimitive.content) }?.toSet(),
        value.getValue("delegationCeiling").present()?.jsonObject?.let(::bindLimits),
    )

    private fun bindLimits(value: JsonObject): PermissionLimits = PermissionLimits(
        value.getValue("maximumAmount").present()?.jsonObject?.let {
            Money(Currency.valueOf(it.getValue("currency").jsonPrimitive.content), it.getValue("minor").jsonPrimitive.long)
        },
        value.getValue("maximumPercentageBasisPoints").present()?.jsonPrimitive?.int,
        value.getValue("noMonetaryCeiling").present()?.jsonPrimitive?.content?.let { NoMonetaryCeiling(Currency.valueOf(it)) },
    )

    /**
     * A bounded public DTO for rendered controlled observations only. These bytes are the
     * frozen semantic JSON, not the production effective-policy codec. No canonical-policy
     * equality, native approval, persistence, history or Master success follows from this DTO.
     */
    fun definition(name: String = "replacement_policy"): LocalEmployeePolicyActivationDefinition {
        val bytes = input(name).toString().encodeToByteArray()
        return try { LocalEmployeePolicyActivationDefinition.capture(originalRequest, policy(name), bytes) }
        finally { bytes.fill(0) }
    }

    fun review(stage: LocalSetupEmployeePolicyStage = LocalSetupEmployeePolicyStage.REVIEW,
        name: String = "replacement_policy"): LocalSetupEmployeePolicyView = LocalSetupEmployeePolicyView(
        reviewId = DomainId.random(), originalRequestId = originalRequest, scope = scope, stage = stage,
        actorId = employee, originalActionId = originalAction,
        nativePhase = if (stage == LocalSetupEmployeePolicyStage.APPROVED) LocalEmployeePolicyActivationPhase.APPROVED
            else LocalEmployeePolicyActivationPhase.PREPARED,
        requested = definition(name), headName = id("named_company_head").value,
        // Synthetic human identifier used as display-only controlled metadata; no credential binding.
        headLogin = id("named_company_head").value,
    )

    fun editor(): LocalSetupEmployeePolicyView = LocalSetupEmployeePolicyView(
        reviewId = DomainId.random(), originalRequestId = originalRequest, scope = scope,
        stage = LocalSetupEmployeePolicyStage.DEFINITION,
    )

    fun assertPolicy(name: String = "replacement_policy", actual: ActivatedLocalPolicy) {
        val expected = input(name)
        assertBranch(expected.getValue("scope").jsonObject, actual.scope)
        assertEquals(expected.getValue("actorId").jsonPrimitive.content, actual.actorId.value, "exact employee")
        assertEquals(expected.getValue("revision").jsonPrimitive.content, actual.revision.value.toString(), "exact revision")
        val expectedGrants = expected.getValue("grants").jsonArray
        assertEquals(expectedGrants.size, actual.grants.size, "complete grant list; no inherited grants")
        expectedGrants.forEachIndexed { index, item ->
            val value = item.jsonObject
            val grant = actual.grants[index]
            val permission = value.getValue("permission").jsonObject
            assertEquals(permission.getValue("action").jsonPrimitive.content, grant.permission.action.name, "grant $index action")
            assertEquals(permission.getValue("verb").jsonPrimitive.content, grant.permission.verb.name, "grant $index verb")
            assertBranch(value.getValue("scope").jsonObject, grant.scope as BranchScope)
            assertEquals(value.getValue("effect").jsonPrimitive.content, grant.effect.name)
            assertEquals(value.getValue("ownerAccess").jsonPrimitive.content, grant.ownerAccess.name)
            assertEquals(value.getValue("namedSubjectId").present()?.jsonPrimitive?.content, grant.namedSubjectId?.value)
            assertEquals(value.getValue("targetIds").present()?.jsonArray?.map { it.jsonPrimitive.content }?.toSet(),
                grant.targetIds?.map { it.value }?.toSet(), "grant $index exact targets, including null")
            assertLimits(value.getValue("limits").jsonObject, grant.limits)
            val ceiling = value.getValue("delegationCeiling").present()
            if (ceiling == null) assertNull(grant.delegationCeiling, "grant $index null delegation ceiling")
            else assertLimits(ceiling.jsonObject, requireNotNull(grant.delegationCeiling))
        }
        assertEquals(expected.getValue("sessionPolicy").jsonObject.getValue("maximumConcurrentSessions").jsonPrimitive.int,
            actual.sessionPolicy.maximumConcurrentSessions)
        val throttle = expected.getValue("throttlePolicy").jsonObject
        assertEquals(throttle.getValue("freeFailures").jsonPrimitive.int, actual.throttlePolicy.freeFailures)
        assertEquals(throttle.getValue("initialDelayMillis").jsonPrimitive.long, actual.throttlePolicy.initialDelayMillis)
        assertEquals(throttle.getValue("maximumDelayMillis").jsonPrimitive.long, actual.throttlePolicy.maximumDelayMillis)
        assertEquals(throttle.getValue("attemptTimeoutMillis").jsonPrimitive.long, actual.throttlePolicy.attemptTimeoutMillis)
        val approval = expected.getValue("approvalPolicy").present()
        if (approval == null) assertNull(actual.approvalPolicy, "absent is not inherited approval")
        else {
            val value = approval.jsonObject
            val actualApproval = requireNotNull(actual.approvalPolicy)
            assertEquals(value.getValue("validForMillis").jsonPrimitive.long, actualApproval.validForMillis)
            assertEquals(value.getValue("namedSelfApprovalActions").jsonArray.map { it.jsonPrimitive.content }.toSet(),
                actualApproval.namedSelfApprovalActions.map { it.name }.toSet())
        }
    }

    private fun assertLimits(expected: JsonObject, actual: PermissionLimits) {
        val amount = expected.getValue("maximumAmount").present()
        if (amount == null) assertNull(actual.maximumAmount)
        else {
            assertEquals(amount.jsonObject.getValue("currency").jsonPrimitive.content, actual.maximumAmount?.currency?.name)
            assertEquals(amount.jsonObject.getValue("minor").jsonPrimitive.content, actual.maximumAmount?.minor?.toString())
        }
        assertEquals(expected.getValue("maximumPercentageBasisPoints").present()?.jsonPrimitive?.int,
            actual.maximumPercentageBasisPoints)
        assertEquals(expected.getValue("noMonetaryCeiling").present()?.jsonPrimitive?.content, actual.noMonetaryCeiling?.currency?.name)
    }

    private fun branch(value: JsonObject): BranchScope = BranchScope(DomainId(value.getValue("organizationId").jsonPrimitive.content),
        DomainId(value.getValue("companyId").jsonPrimitive.content), DomainId(value.getValue("branchId").jsonPrimitive.content))
    private fun assertBranch(expected: JsonObject, actual: BranchScope) {
        assertEquals(expected.getValue("organizationId").jsonPrimitive.content, actual.organizationId.value)
        assertEquals(expected.getValue("companyId").jsonPrimitive.content, actual.companyId.value)
        assertEquals(expected.getValue("branchId").jsonPrimitive.content, actual.branchId.value)
    }
    private fun JsonElement.present(): JsonElement? = takeUnless { it == JsonNull }
}

